import{_ as t,o,c as s,a2 as n}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Server Provisioning & Hosting Managers","description":"","frontmatter":{},"headers":[],"relativePath":"admin/servers.md","filePath":"admin/servers.md","lastUpdated":null}'),r={name:"admin/servers.md"};function d(a,e,l,i,c,g){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="server-provisioning-hosting-managers" tabindex="-1">Server Provisioning &amp; Hosting Managers <a class="header-anchor" href="#server-provisioning-hosting-managers" aria-label="Permalink to &quot;Server Provisioning &amp; Hosting Managers&quot;">​</a></h1><p>FOSSBilling integrates with industry-standard control panels to provision web hosting, email accounts, and database quotas automatically upon invoice payment.</p><hr><h2 id="🖥️-supported-control-panels" tabindex="-1">🖥️ Supported Control Panels <a class="header-anchor" href="#🖥️-supported-control-panels" aria-label="Permalink to &quot;🖥️ Supported Control Panels&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Control Panel</th><th style="text-align:left;">Driver ID</th><th style="text-align:left;">Authentication</th><th style="text-align:left;">Supported Actions</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>cPanel / WHM</strong></td><td style="text-align:left;"><code>cpanel</code></td><td style="text-align:left;">WHM API Token / Access Hash</td><td style="text-align:left;">Create, Suspend, Unsuspend, Terminate, Change Password</td></tr><tr><td style="text-align:left;"><strong>Plesk</strong></td><td style="text-align:left;"><code>plesk</code></td><td style="text-align:left;">REST API Key / Secret Key</td><td style="text-align:left;">Create Subscription, Suspend, Unsuspend, Delete, Password</td></tr><tr><td style="text-align:left;"><strong>DirectAdmin</strong></td><td style="text-align:left;"><code>directadmin</code></td><td style="text-align:left;">DirectAdmin Login Key / API</td><td style="text-align:left;">CMD_API_ACCOUNT_USER, Suspend, Unsuspend, Delete</td></tr><tr><td style="text-align:left;"><strong>HestiaCP</strong></td><td style="text-align:left;"><code>hestia</code></td><td style="text-align:left;">Hestia API Access Key</td><td style="text-align:left;"><code>v-add-user</code>, <code>v-add-web-domain</code>, <code>v-suspend-user</code>, <code>v-delete-user</code></td></tr><tr><td style="text-align:left;"><strong>CentOS Web Panel (CWP)</strong></td><td style="text-align:left;"><code>cwp</code></td><td style="text-align:left;">CWP API Key</td><td style="text-align:left;"><code>/v1/account</code>, <code>/v1/account/suspend</code>, <code>/v1/account/delete</code></td></tr><tr><td style="text-align:left;"><strong>Custom Webhooks</strong></td><td style="text-align:left;"><code>custom</code></td><td style="text-align:left;">HMAC-SHA256 Secret Header</td><td style="text-align:left;">JSON Webhooks for custom Kubernetes / Docker / VPS nodes</td></tr></tbody></table><hr><h2 id="⚙️-adding-a-new-server" tabindex="-1">⚙️ Adding a New Server <a class="header-anchor" href="#⚙️-adding-a-new-server" aria-label="Permalink to &quot;⚙️ Adding a New Server&quot;">​</a></h2><ol><li>Navigate to <strong>Servers</strong> (<code>/servers</code>) in the Administrator Portal.</li><li>Click <strong>Add New Server</strong>.</li><li>Enter Server Details: <ul><li><strong>Name:</strong> e.g., <code>cPanel US-East-1 Cluster</code></li><li><strong>Hostname / IP:</strong> e.g., <code>whm.provider.com</code> (or IP address)</li><li><strong>Driver:</strong> Choose from dropdown (<code>cpanel</code>, <code>plesk</code>, <code>directadmin</code>, <code>hestia</code>, <code>cwp</code>, <code>custom</code>)</li><li><strong>Port:</strong> (Default: <code>2087</code> for WHM, <code>8443</code> for Plesk, <code>2222</code> for DirectAdmin, <code>8083</code> for HestiaCP)</li><li><strong>Access Key / API Token:</strong> Paste your secure API token.</li></ul></li><li>Click <strong>Test Connection</strong> to verify live communication with the server daemon.</li><li>Save the server and assign it to your hosting products.</li></ol>',8)])])}const f=t(r,[["render",d]]);export{u as __pageData,f as default};
